/// <summary>
/// Sales order Ready for Pricing Business events
/// </summary>
[BusinessEvents(classStr(METSOReadyForPricingBusinessEventContract), '@MET:ReadyForPricing', '@MET:ReadyForPricingBEDesc', ModuleAxapta::SalesOrder)]
public final class METSOReadyForPricingBusinessEvent extends BusinessEventsBase
{
    private SalesTable salestable;
}

Method.Source:
/// <summary>
/// Constructs a new METSOReadyForPricingBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METSOReadyForPricingBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METSOReadyForPricingBusinessEventContract::newFromSalesTable(salestable);
}

    public SalesTable parmSalesTable(SalesTable _salesTable = salestable)
    {
        salestable = _salesTable;

        return salestable;
    }

    /// <summary>
    /// Creates a <c>METSOReadyForPricingBusinessEvent</c> from a <c>SalesTable</c> record.
    /// </summary>
    /// <param name = "_salesTable"> A sales order record.</param>
    /// <returns>An instance of <c>METSOReadyForPricingBusinessEvent</c>.</returns>
    public static METSOReadyForPricingBusinessEvent newFromSalesTable(SalesTable _salesTable)
    {
        METSOReadyForPricingBusinessEvent businessEvent = new METSOReadyForPricingBusinessEvent();
        businessEvent.parmSalesTable(_salesTable);

        return businessEvent;
    }
